import{_ as a,o as n,c as e,y as p}from"./chunks/framework.CNTkXYA8.js";const g=JSON.parse('{"title":"【OpenGL】学习笔记#5","description":"","frontmatter":{"title":"【OpenGL】学习笔记#5","date":"2020-08-27T20:16:00.000Z"},"headers":[],"relativePath":"blog/opengl-5-13573649.md","filePath":"source/old_posts/opengl-5-13573649.md"}'),i={name:"blog/opengl-5-13573649.md"};function t(l,s,c,d,o,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h2 id="一、帧缓冲" tabindex="-1">一、帧缓冲 <a class="header-anchor" href="#一、帧缓冲" aria-label="Permalink to &quot;一、帧缓冲&quot;">​</a></h2><p>什么是帧缓冲？可以理解为GPU在渲染前预先准备的一个区域，之后将把它渲染成屏幕上的像素。但是，帧缓冲本身并不储存数据，仅仅储存指向数据的指针。所以，帧缓冲需要绑定几个缓冲区，我们特殊地称它们为附件：颜色附件，深度缓冲附件，模板缓冲附件。需要注意的是，一个完整的帧缓冲必须包括一个颜色附件。</p><p>除了这种分类之外，附件还可以分为纹理附件和渲染缓冲对象(RBO，Render Buffer Object)。其中，纹理附件就是颜色附件，RBO分为深度缓冲附件和模板缓冲附件。让我们来列一个树形图。</p><p>帧缓冲－－[纹理附件]－－颜色附件</p><p>|</p><p>[渲染缓冲附件]－－深度缓冲附件</p><p>｜</p><p>－－模板缓冲附件</p><p>为什么要讲到帧缓冲呢？因为帧缓冲是后期处理相当重要的部分。例如阴影，模糊，反相等后期处理都要依靠帧缓冲来实现。打个比方，帧缓冲就好像是拍出来的一张照片，可以让我们PS。</p><p>此处的PS便是着色器。OpenGL提供了可以让我们编辑的帧缓冲，好伟大！我们可以把一张帧缓冲保存的2D纹理或深度缓冲获得为一个句柄，在后面直接使用，塞进着色器里。</p><p>说了这么多，来看看代码吧，让我们以用着色器编辑一个帧缓冲为例子：</p><p>首先生成并绑定一个帧缓冲：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLuint FramebufferName = 0;</span></span>
<span class="line"><span>    glGenFramebuffers(1, &amp;FramebufferName);</span></span>
<span class="line"><span>    glBindFramebuffer(GL_FRAMEBUFFER, FramebufferName);</span></span></code></pre></div><p>生成一个纹理：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLuint renderedTexture;</span></span>
<span class="line"><span>    glGenTextures(1, &amp;renderedTexture);</span></span></code></pre></div><p>状态机不解释：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glBindTexture(GL_TEXTURE_2D, renderedTexture);</span></span></code></pre></div><p>由于帧缓冲必须包含一个颜色附件，所以接下来对之前绑定的纹理填充一个空的图像（最后一个参数0代表空,empty）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glTexImage2D(GL_TEXTURE_2D, 0,GL_RGB, windowWidth, windowHeight, 0,GL_RGB, GL_UNSIGNED_BYTE, 0);</span></span></code></pre></div><p>可　　怜　　的　　过　　滤（性能upup），设置过滤模式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);</span></span>
<span class="line"><span>    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);</span></span>
<span class="line"><span>    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);</span></span>
<span class="line"><span>    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);</span></span></code></pre></div><p>由于我们要渲染一个3D模型，所以要进行深度测试，所以来生成并绑定一个渲染缓冲区，将要作为我们的RBO：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLuint depthrenderbuffer;</span></span>
<span class="line"><span>    glGenRenderbuffers(1, &amp;depthrenderbuffer);</span></span>
<span class="line"><span>    glBindRenderbuffer(GL_RENDERBUFFER, depthrenderbuffer);</span></span></code></pre></div><p>由于OpenGL只知道这是个渲染缓冲区，对其中的数据格式和大小全然不知，所以我们得告诉它，使用glRenderbufferStorage来指定RBO的数据格式和大小，此处指定为深度缓冲区：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glRenderbufferStorage(GL_RENDERBUFFER, GL_DEPTH_COMPONENT, windowWidth, windowHeight);</span></span></code></pre></div><p>对于此函数，第一个参数必须填GL_RENDERBUFFER，第二个指定了类型为深度缓冲，还可以是GL_RGB，GL_RGBA，剩下的两个参数指定了数据长宽，这里设置为屏幕大小。</p><p>接下来开始为帧缓冲绑定附件，将此深度缓冲绑定为深度附件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_DEPTH_ATTACHMENT, GL_RENDERBUFFER, depthrenderbuffer);</span></span></code></pre></div><p>第二个参数指定了类型为深度附件。</p><p>然后绑定纹理附件，这个比较特殊，先看代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glFramebufferTexture(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, renderedTexture, 0);</span></span></code></pre></div><p>可以看到，第二个参数并不是指定的类型，而是GL_COLOR_ATTACHMENT0，这意味着什么呢，这意味着颜色附件可以有多个，0代表的是颜色附件的位置。同时我们也发现RBO只能有一个，因为它直接指定了类型。</p><p>所以，我们就需要指定接下来渲染时需要渲染到哪些颜色附件上，这次我们只渲染到GL_COLOR_ATTACHMENT0上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLenum DrawBuffers[1] = {GL_COLOR_ATTACHMENT0};</span></span>
<span class="line"><span>    glDrawBuffers(1, DrawBuffers);</span></span></code></pre></div><p>不需要多说了吧。</p><p>终于，帧缓冲的前置操作完成了。这时需要检查你的帧缓冲是否完整，否则会有很可怕的错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if(glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE)</span></span>
<span class="line"><span>        return false;</span></span></code></pre></div><p>经常check是好习惯呦～</p><p>由于我们要把帧缓冲的图像经过处理绘制到屏幕上，所以一会渲染的时候将要分两个步骤：第一步，按照往常的操作渲染，但是在渲染前把渲染目标绑定到我们自定义的帧缓冲上，此为离屏渲染。然后，通过颜色附件获得渲染得到的深度缓冲和纹理，再把它们传到着色器里处理，作为2D纹理渲染到一个屏幕大小的四边形上。</p><p>那么，下面开始定义四边形：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static const GLfloat g_quad_vertex_buffer_data[] = {</span></span>
<span class="line"><span>        -1.0f, -1.0f, 0.0f,</span></span>
<span class="line"><span>         1.0f, -1.0f, 0.0f,</span></span>
<span class="line"><span>        -1.0f,  1.0f, 0.0f,</span></span>
<span class="line"><span>        -1.0f,  1.0f, 0.0f,</span></span>
<span class="line"><span>         1.0f, -1.0f, 0.0f,</span></span>
<span class="line"><span>         1.0f,  1.0f, 0.0f,</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    GLuint quad_vertexbuffer;</span></span>
<span class="line"><span>    glGenBuffers(1, &amp;quad_vertexbuffer);</span></span>
<span class="line"><span>    glBindBuffer(GL_ARRAY_BUFFER, quad_vertexbuffer);</span></span>
<span class="line"><span>    glBufferData(GL_ARRAY_BUFFER, sizeof(g_quad_vertex_buffer_data), g_quad_vertex_buffer_data, GL_STATIC_DRAW);</span></span></code></pre></div><p>定义顶点缓冲，里面包括的是一个2D充满屏幕的四边形的顶点，注意此时顶点依然是3维的格式，只不过Z=0，相当于2D。</p><p>好了，一切都准备好了，下面进入主循环：</p><p>首先把渲染目标绑定到我们定义的帧缓冲里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glBindFramebuffer(GL_FRAMEBUFFER, FramebufferName);</span></span></code></pre></div><p>这里是渲染操作...</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glUseProgram(programID);</span></span></code></pre></div><p>(这里使用通常的着色器)</p><p>这里是渲染操作...</p><p>然后重头戏来了，开始渲染四边形，先把渲染目标绑定到默认帧缓冲：这个帧缓冲将会直接被GPU提取渲染：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glBindFramebuffer(GL_FRAMEBUFFER, 0);</span></span></code></pre></div><p>这里是渲染操作...</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>glUseProgram(quad_programID);</span></span></code></pre></div><p>(使用第二个着色器，这个着色器只负责渲染一个2D纹理并稍稍处理)</p><p>这里是渲染操作...</p><p>怎么样，这样就完成了呢，小朋友们学会了吗？（狗头）</p><p>咳咳，说了这么多，第二个着色器长啥样呢，仅仅渲染一个2D纹理的着色器，来看吧：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#version 330 core</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Input vertex data, different for all executions of this shader.</span></span>
<span class="line"><span>layout(location = 0) in vec3 vertexPosition_modelspace;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Output data ; will be interpolated for each fragment.</span></span>
<span class="line"><span>out vec2 UV;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void main(){</span></span>
<span class="line"><span>    gl_Position =  vec4(vertexPosition_modelspace,1);</span></span>
<span class="line"><span>    UV = (vertexPosition_modelspace.xy+vec2(1,1))/2.0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>出人意料的简单呢......仅仅传出一个UV坐标。不过，这里要注意，我们的顶点坐标xy的范围是[-1,1]，而UV坐标uv的范围是[0,1]，所以需要(xy+(1,1))/2来转换。</p><p>看片元着色器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#version 330 core</span></span>
<span class="line"><span></span></span>
<span class="line"><span>in vec2 UV;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>out vec3 color;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uniform sampler2D renderedTexture;</span></span>
<span class="line"><span>uniform float time;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void main(){</span></span>
<span class="line"><span>    color = texture( renderedTexture, UV + 0.005*vec2( sin(time+1024.0*UV.x),cos(time+768.0*UV.y)) ).xyz ;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用时间来做一个偏移量，不多说了吧。</p><p>那么看看结果吧：</p><p><img src="https://img2020.cnblogs.com/blog/1389232/202008/1389232-20200827201548430-575685414.png" alt=""></p><p>像素会随着时间的变化慢慢移动喔！</p>`,65)])])}const h=a(i,[["render",t]]);export{g as __pageData,h as default};
